INSERT INTO "strategies" ("id", "slug", "name", "description", "kind", "status", "source_ref", "tags", "section", "params") VALUES
  ('strategy-seed-long-calendar-spread', 'long-calendar-spread', 'Long Calendar Spread (call or put)', 'Sell a near-expiry option and buy the same strike at about twice the time to expiry (Instagram reel DfcycUDCjgD, Spreads Trading: sell the ~100-day call, buy the ~200-day call). Entry only when far-leg IV is at most 1.10x near-leg IV; exit both legs at 1.5x the debit or at the near expiry; maximum loss = the debit. MODELED backtest (Black-Scholes from VIX/VIX3M, VXN or 60-day realized vol; no option-chain history), 2011-01 to 2026-11, after costs. Pre-set test (one config passing on 3 of SPY, QQQ, TQQQ, SOXL incl. SPY or QQQ): FAIL. Only the 100/200-day 0.30-delta call calendar passes, on SPY (mean +33.8% per cycle, t 11.25) and QQQ (+27.8%, t 6.00); at the money it fails everywhere and loses on TQQQ and SOXL. With 2% instead of 3% slippage on TQQQ/SOXL options config C would pass (cost-sensitive). Reel check (its SOXL 100-strike example at the 2026-11-06 close): cost about USD 323 at the mid, peak about USD 2,180 only at SOXL 100. Spec: docs/specs/strategies/long-calendar-spread.md', 'native', 'backtested', 'scripts/research/calendar-spread.ts', '["options","calendar-spread","modeled","failed"]'::jsonb, 'Options', '[]'::jsonb)
